def re_arrange(arr):
    for i in range(len(arr)):
        if arr[i] >= 0:
            j = i + 1
            while j < len(arr) and arr[j] >= 0:
                j += 1
            if j < len(arr):
                arr[i], arr[j] = arr[j], arr[i]
        else:
            j = i + 1
            while j < len(arr) and arr[j] < 0:
                j += 1
            if j < len(arr):
                arr[i], arr[j] = arr[j], arr[i]
    return arr

def heapify(arr, n, i):
    largest = i
    left = 2 * i + 1
    right = 2 * i + 2

    if left < n and arr[left] > arr[largest]:
        largest = left

    if right < n and arr[right] > arr[largest]:
        largest = right

    if largest != i:
        arr[i], arr[largest] = arr[largest], arr[i]
        heapify(arr, n, largest)

def heap_sort(arr):
    n = len(arr)

    for i in range(n // 2 - 1, -1, -1):
        heapify(arr, n, i)

    for i in range(n - 1, 0, -1):
        arr[i], arr[0] = arr[0], arr[i]
        heapify(arr, i, 0)

    return arr

def permutation_coefficient(n, k):
    if k > n:
        return 0
    result = 1
    for i in range(k):
        result *= (n - i)
    return result

def count_element_freq(nested_tuple):
    freq_dict = {}
    for item in nested_tuple:
        if isinstance(item, tuple):
            for sub_item in item:
                if sub_item in freq_dict:
                    freq_dict[sub_item] += 1
                else:
                    freq_dict[sub_item] = 1
        else:
            if item in freq_dict:
                freq_dict[item] += 1
            else:
                freq_dict[item] = 1
    return freq_dict
